%[text] # Controller and Environment - Simulation Case
model_name = "HarnessModel_CtrlEnv";
load_system(model_name)

HarnessSetup_CtrlEnv

sim_in = Simulink.SimulationInput(model_name);

sim_in = setBlockParameter(sim_in, ...
  model_name + "/Controller and Environment/Vehicle speed reference", ...
  ReferencedSubsystem = "VehSpdRef_FTP75_refsub");

sim_in = setModelParameter(sim_in, StopTime = "2474");

applyToModel(sim_in)

sim_out = sim(sim_in);

sim_data = extractTimetable(sim_out.logsout);

% Specify the signal logging names in the model.
signal_names = [
  "Motor torque command"
  "Vehicle speed reference kph"
  "Vehicle speed kph"
  "Motor speed reference"
  "Motor speed"
  ];

for idx = 1 : numel(signal_names) %[output:group:2d875960]
  SignalUtil1.plotTimedData( TimedData = sim_data, ... %[output:0b61fbef] %[output:4c07950a] %[output:89a8a3ac] %[output:074c68af] %[output:19b4c2ca]
    SignalName = signal_names(idx), ... %[output:0b61fbef] %[output:4c07950a] %[output:89a8a3ac] %[output:074c68af] %[output:19b4c2ca]
    FigureHeight = 150 ) %[output:0b61fbef] %[output:4c07950a] %[output:89a8a3ac] %[output:074c68af] %[output:19b4c2ca]
end  % for %[output:group:2d875960]
